/* From Uiverse.io by gharsh11032000 - Tags: form, password, simple form, forgot password */
.__UIV_SCOPE__ .form-container {
  max-width: 400px;
  background-color: #fff;
  padding: 32px 24px;
  font-size: 14px;
  font-family: inherit;
  color: #212121;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-sizing: border-box;
  border-radius: 10px;
  box-shadow: 0px 0px 3px rgba(0, 0, 0, 0.084), 0px 2px 3px rgba(0, 0, 0, 0.168);
}

.__UIV_SCOPE__ .form-container button:active {
  scale: 0.95;
}

.__UIV_SCOPE__ .form-container .logo-container {
  text-align: center;
  font-weight: 600;
  font-size: 18px;
}

.__UIV_SCOPE__ .form-container .form {
  display: flex;
  flex-direction: column;
}

.__UIV_SCOPE__ .form-container .form-group {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.__UIV_SCOPE__ .form-container .form-group label {
  display: block;
  margin-bottom: 5px;
}

.__UIV_SCOPE__ .form-container .form-group input {
  width: 100%;
  padding: 12px 16px;
  border-radius: 6px;
  font-family: inherit;
  border: 1px solid #ccc;
}

.__UIV_SCOPE__ .form-container .form-group input::placeholder {
  opacity: 0.5;
}

.__UIV_SCOPE__ .form-container .form-group input:focus {
  outline: none;
  border-color: #1778f2;
}

.__UIV_SCOPE__ .form-container .form-submit-btn {
  display: flex;
  justify-content: center;
  align-items: center;
  font-family: inherit;
  color: #fff;
  background-color: #212121;
  border: none;
  width: 100%;
  padding: 12px 16px;
  font-size: inherit;
  gap: 8px;
  margin: 12px 0;
  cursor: pointer;
  border-radius: 6px;
  box-shadow: 0px 0px 3px rgba(0, 0, 0, 0.084), 0px 2px 3px rgba(0, 0, 0, 0.168);
}

.__UIV_SCOPE__ .form-container .form-submit-btn:hover {
  background-color: #313131;
}

.__UIV_SCOPE__ .form-container .link {
  color: #1778f2;
  text-decoration: none;
}

.__UIV_SCOPE__ .form-container .signup-link {
  align-self: center;
  font-weight: 500;
}

.__UIV_SCOPE__ .form-container .signup-link .link {
  font-weight: 400;
}

.__UIV_SCOPE__ .form-container .link:hover {
  text-decoration: underline;
}
